const item = $input.first();
const body = item.json.body || {};
const env = (k, d) => {
  try {
    const v = $env[k];
    return (v === undefined || v === '') ? d : v;
  } catch (e) {
    return d;
  }
};

const defaultModel = env('DPDP_DEFAULT_MODEL', 'meta-llama/llama-3.3-70b-instruct');
const cfg = {
  backend_url: env('DPDP_BACKEND_URL', 'http://dpdp-backend:8000'),
  redact_pii_before_llm: env('DPDP_REDACT_PII_BEFORE_LLM', 'true') === 'true',
  models: {
    a0: env('DPDP_MODEL_A0', defaultModel),
    a1: env('DPDP_MODEL_A1', defaultModel),
    a2: env('DPDP_MODEL_A2', defaultModel),
    a3: env('DPDP_MODEL_A3', defaultModel),
    a4: env('DPDP_MODEL_A4', defaultModel),
    a5: env('DPDP_MODEL_A5', defaultModel),
    a6: env('DPDP_MODEL_A6', defaultModel),
    a7: env('DPDP_MODEL_A7', defaultModel)
  },
  temperature: Number(env('DPDP_TEMPERATURE', '0.1')),
  max_tokens: Number(env('DPDP_MAX_TOKENS', '4096')),
  max_file_mb: Number(env('DPDP_MAX_FILE_MB', '15')),
  max_qa_revisions: 2,
  max_human_revisions: 2,
  notify_webhook_url: env('DPDP_NOTIFY_WEBHOOK_URL', '')
};

const errors = [];
const idRe = /^[A-Za-z0-9_-]{1,64}$/;
const tenant_id = String(body.tenant_id || 'default_tenant').trim();
const project_id = String(body.project_id || 'default_project').trim();
const client_name = String(body.client_name || 'Organization').trim().slice(0, 120);
const doc_hint = String(body.document_type_hint || 'auto').trim();
const consentVal = body.external_llm_consent === undefined ? 'true' : String(body.external_llm_consent).toLowerCase();

if (!idRe.test(tenant_id)) errors.push('tenant_id invalid (allowed: A-Z a-z 0-9 _ - ; max 64 chars)');
if (!idRe.test(project_id)) errors.push('project_id invalid (allowed: A-Z a-z 0-9 _ - ; max 64 chars)');
if (consentVal !== 'true') {
  errors.push('external_llm_consent=true is required before transmitting document excerpts to Gemini or OpenRouter.');
}

const allowed = {
  pdf: ['application/pdf', 'application/octet-stream'],
  docx: ['application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/octet-stream'],
  xlsx: ['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/octet-stream'],
  csv: ['text/csv', 'application/csv', 'application/vnd.ms-excel', 'text/plain', 'application/octet-stream'],
  txt: ['text/plain', 'application/octet-stream'],
  md: ['text/markdown', 'text/plain', 'application/octet-stream']
};

const bin = item.binary || {};
const keys = Object.keys(bin);
let outBinary, fileName = '', mime = '', size = 0;

if (keys.length === 0) {
  errors.push('Upload at least one file under multipart/form-data field "file".');
} else {
  const b = bin[keys[0]];
  fileName = String(b.fileName || '');
  mime = String(b.mimeType || 'application/octet-stream').toLowerCase();
  const ext = (fileName.split('.').pop() || '').toLowerCase();
  if (!allowed[ext]) {
    errors.push(`Unsupported extension ".${ext}". Allowed: ${Object.keys(allowed).join(', ')}`);
  } else if (!allowed[ext].includes(mime)) {
    errors.push(`MIME type "${mime}" does not match file extension ".${ext}".`);
  }
  const buf = await this.helpers.getBinaryDataBuffer(0, keys[0]);
  size = buf.length;
  if (size === 0) errors.push('Uploaded file is empty (0 bytes).');
  if (size > cfg.max_file_mb * 1024 * 1024) errors.push(`File exceeds ${cfg.max_file_mb} MB limit.`);
  outBinary = { data: b };
}

const job_id = 'job_' + $execution.id;

const out = {
  json: {
    valid: errors.length === 0,
    errors,
    job_id,
    tenant_id,
    project_id,
    client_name,
    document_type_hint: doc_hint,
    file_name: fileName,
    file_size: size,
    mime,
    config: cfg,
    received_at: new Date().toISOString()
  }
};
if (outBinary) out.binary = outBinary;
return [out];

