const v = $('Validate Input & Config').last();
return [{
  json: v.json,
  binary: v.binary
}];

const r = $input.first().json;
const v = $('Validate Input & Config').last().json;
const chunks = Array.isArray(r.chunks) ? r.chunks : [];
const clean = chunks.filter(c => c && c.evidence_id && typeof c.text === 'string' && c.text.trim().length > 0);
const totalChars = clean.reduce((acc, c) => acc + c.text.length, 0);

if (!r.document_id) throw new Error('Extraction failed: missing document_id from FastAPI backend.');
if (clean.length === 0 || totalChars < 30) {
  throw new Error(`Extraction produced insufficient readable text (${totalChars} chars) for job ${v.job_id}.`);
}

const seen = new Set();
const countsByType = { EMAIL: 0, PHONE: 0, PAN: 0, GOVT_ID: 0 };
const maskedLocations = [];

for (const c of clean) {
  if (seen.has(c.evidence_id)) throw new Error(`Duplicate evidence_id detected: ${c.evidence_id}`);
  seen.add(c.evidence_id);
  const em = (c.text.match(/\[REDACTED_EMAIL\]/g) || []).length;
  const ph = (c.text.match(/\[REDACTED_PHONE\]/g) || []).length;
  const pn = (c.text.match(/\[REDACTED_PAN\]/g) || []).length;
  const ad = (c.text.match(/\[REDACTED_AADHAAR\]/g) || []).length;
  countsByType.EMAIL += em;
  countsByType.PHONE += ph;
  countsByType.PAN += pn;
  countsByType.GOVT_ID += ad;
  if (em + ph + pn + ad > 0) {
    maskedLocations.push({
      evidence_id: c.evidence_id,
      locator: c.locator,
      masked_tokens_in_chunk: em + ph + pn + ad,
      excerpt_with_masks: c.text.slice(0, 220)
    });
  }
}

const totalMasked = countsByType.EMAIL + countsByType.PHONE + countsByType.PAN + countsByType.GOVT_ID;
const backendRed = r.redaction_summary || {};
const redactionSummary = {
  pii_redaction_enabled: r.pii_redacted === true,
  total_masked_tokens: backendRed.total_masked_tokens ?? totalMasked,
  counts_by_type: {
    EMAIL: backendRed.counts_by_type?.EMAIL ?? countsByType.EMAIL,
    PHONE: backendRed.counts_by_type?.PHONE ?? countsByType.PHONE,
    PAN: backendRed.counts_by_type?.PAN ?? countsByType.PAN,
    GOVT_ID: backendRed.counts_by_type?.AADHAAR ?? countsByType.GOVT_ID,
    AADHAAR: backendRed.counts_by_type?.AADHAAR ?? countsByType.GOVT_ID
  },
  masked_locations: maskedLocations
};

const formattedLines = clean.map(c => `[${c.evidence_id}|${c.locator || 'loc'}] ${c.text}`);
const fullDigest = formattedLines.join('\n');
const inlinePreviewLimit = 32000;
const isInlineTruncated = fullDigest.length > inlinePreviewLimit;
const inlineEvidenceText = isInlineTruncated
  ? fullDigest.slice(0, inlinePreviewLimit) + `\n...[INLINE PREVIEW TRUNCATED AT ${inlinePreviewLimit} CHARS. CALL THE search_evidence TOOL TO RETRIEVE REMAINING CHUNKS]...`
  : fullDigest;

return [{
  json: {
    job_id: v.job_id,
    tenant_id: v.tenant_id,
    project_id: v.project_id,
    client_name: v.client_name,
    config: v.config,
    document: {
      document_id: r.document_id,
      filename: r.filename || v.file_name,
      detected_mime: r.detected_mime || v.mime,
      sha256: r.sha256 || null,
      doc_type_hint: v.document_type_hint,
      page_count: r.page_count || null,
      sheet_names: r.sheet_names || [],
      duplicate_of: r.duplicate_of || null,
      extraction_complete: r.extraction_complete !== false,
      pii_redacted: r.pii_redacted === true,
      redaction_summary: redactionSummary
    },
    chunks: clean,
    chunk_count: clean.length,
    total_chars: totalChars,
    inline_truncated: isInlineTruncated,
    inline_evidence_text: inlineEvidenceText,
    warnings: [].concat(r.warnings || [], isInlineTruncated ? ['Document exceeds inline window; agents must use search_evidence tool for tail chunks.'] : [])
  }
}];

const ext = $('Validate Extraction & Build Evidence Store').last().json;
return JSON.stringify({
  job_id: ext.job_id,
  tenant_id: ext.tenant_id,
  project_id: ext.project_id,
  document: ext.document,
  chunk_count: ext.chunk_count,
  total_chars: ext.total_chars,
  inline_truncated: ext.inline_truncated,
  locators: ext.chunks.map(c => ({ evidence_id: c.evidence_id, locator: c.locator })),
  warnings: ext.warnings
});

const ext = $('Validate Extraction & Build Evidence Store').last().json;
return JSON.stringify({
  job_id: ext.job_id,
  tenant_id: ext.tenant_id,
  project_id: ext.project_id,
  document: ext.document,
  chunk_count: ext.chunk_count,
  total_chars: ext.total_chars,
  inline_truncated: ext.inline_truncated,
  locators: ext.chunks.map(c => ({ evidence_id: c.evidence_id, locator: c.locator })),
  warnings: ext.warnings
});

const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{');
const e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 0 (Orchestrator) did not return a valid JSON object.');
const parsed = JSON.parse(cleaned.slice(s, e + 1));
for (const k of ['document_manifest', 'processing_plan', 'required_agents']) {
  if (!(k in parsed)) throw new Error(`Agent 0 output missing required key: ${k}`);
}
parsed.job_id = ext.job_id;
parsed.project_id = ext.project_id;
parsed.execution_status = 'in_progress';
return [{ json: { agent: 'A0', plan: parsed } }];

const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const validEvIds = new Set(ext.chunks.map(c => c.evidence_id));
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 1 did not return valid JSON.');
const data = JSON.parse(cleaned.slice(s, e + 1));
if (!Array.isArray(data.documents)) throw new Error('Agent 1 output missing documents[] array.');

for (const doc of data.documents) {
  for (const sec of (doc.sections || [])) {
    sec.evidence_ids = (sec.evidence_ids || []).filter(id => validEvIds.has(id));
  }
}
return [{ json: { agent: 'A1', data } }];

const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const validEvIds = new Set(ext.chunks.map(c => c.evidence_id));
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 2 did not return valid JSON.');
const data = JSON.parse(cleaned.slice(s, e + 1));
if (!Array.isArray(data.data_principal_categories) || !Array.isArray(data.personal_data_items)) {
  throw new Error('Agent 2 output missing data_principal_categories or personal_data_items.');
}
for (const item of data.personal_data_items) {
  item.evidence_ids = (item.evidence_ids || []).filter(id => validEvIds.has(id));
  if (item.evidence_ids.length === 0) item.explicit_or_inferred = 'inferred';
}
return [{ json: { agent: 'A2', data } }];

