const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const validEvIds = new Set(ext.chunks.map(c => c.evidence_id));
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 3 did not return valid JSON.');
const data = JSON.parse(cleaned.slice(s, e + 1));
if (!Array.isArray(data.activities) || data.activities.length === 0) {
  throw new Error('Agent 3 returned no processing activities.');
}

const seenIds = new Set();
data.activities = data.activities.map((a, idx) => {
  let id = String(a.activity_id || '').trim() || `ACT-${String(idx + 1).padStart(3, '0')}`;
  if (seenIds.has(id)) id = `${id}_${idx + 1}`;
  seenIds.add(id);
  a.activity_id = id;
  a.evidence_ids = (Array.isArray(a.evidence_ids) ? a.evidence_ids : []).filter(ev => validEvIds.has(ev));
  a.verification_status = 'pending_review';
  return a;
});
return [{ json: { agent: 'A3', data } }];

const q = String(query || '').trim();
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const chunks = ext.chunks || [];
if (!q || q.toUpperCase() === 'ALL_IDS') {
  return JSON.stringify(chunks.map(c => ({ evidence_id: c.evidence_id, locator: c.locator, preview: c.text.slice(0, 140) })));
}
const requestedIds = q.split(',').map(s => s.trim().toUpperCase()).filter(s => s.startsWith('EV-'));
if (requestedIds.length > 0) {
  const found = chunks.filter(c => requestedIds.includes(c.evidence_id.toUpperCase()));
  return JSON.stringify(found);
}
const kw = q.toLowerCase();
const matches = chunks.filter(c => c.text.toLowerCase().includes(kw) || (c.locator && c.locator.toLowerCase().includes(kw))).slice(0, 25);
return JSON.stringify(matches);

