parameters.jsCode:
try {
  const items = $('Parse & Validate A3').all();
  if (!Array.isArray(items) || items.length === 0) {
    throw new Error('Parse & Validate A3 has not executed yet.');
  }
  const latestItem = items[items.length - 1];
  const a3 = latestItem?.json?.data;
  if (!a3 || !Array.isArray(a3.activities)) {
    throw new Error('Processing activities array is missing from Agent 3.');
  }
  return JSON.stringify({
    success: true,
    total_activities: a3.activities.length,
    activities: a3.activities
  });
} catch (error) {
  throw new Error(`Processing activities retrieval failed: ${error.message}`);
}

const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const validEvIds = new Set(ext.chunks.map(c => c.evidence_id));
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 4 did not return valid JSON.');
const data = JSON.parse(cleaned.slice(s, e + 1));
if (!Array.isArray(data.entities) || !Array.isArray(data.flows)) {
  throw new Error('Agent 4 output missing entities[] or flows[].');
}

const entMap = new Set();
data.entities = data.entities.filter(ent => {
  if (!ent || !ent.entity_id || !ent.name || entMap.has(ent.entity_id)) return false;
  entMap.add(ent.entity_id);
  ent.evidence_ids = (ent.evidence_ids || []).filter(id => validEvIds.has(id));
  return true;
});

data.flows = data.flows.filter(f => {
  if (!f || !entMap.has(f.source_entity_id) || !entMap.has(f.destination_entity_id)) return false;
  f.evidence_ids = (f.evidence_ids || []).filter(id => validEvIds.has(id));
  if (f.evidence_ids.length === 0) f.explicit_or_inferred = 'inferred';
  return true;
});

return [{ json: { agent: 'A4', data } }];

