const backendUrl = 'http://host.docker.internal:8000';
let apiKey;
try {
  apiKey = $env['DPDP_BACKEND_API_KEY'] || '';
} catch (error) {
  throw new Error('Cannot access DPDP_BACKEND_API_KEY. Check n8n environment configuration.');
}
if (!apiKey) {
  throw new Error('DPDP_BACKEND_API_KEY is missing.');
}
let catResp;
try {
  catResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${backendUrl}/api/v1/catalogue/dpdp`,
    headers: { 'X-API-Key': apiKey },
    json: true,
    timeout: 15000
  });
} catch (error) {
  throw new Error(`DPDP catalogue validation request failed: ${error.message}`);
}
if (!Array.isArray(catResp.requirements)) {
  throw new Error('Catalogue response is missing requirements[].');
}
const allowedReqIds = new Set(catResp.requirements.map(r => r.requirement_id));
const cleaned = String(rawOut)
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('Agent 5 did not return valid JSON.');
}
let data;
try {
  data = JSON.parse(cleaned.slice(start, end + 1));
} catch (error) {
  throw new Error(`Agent 5 JSON parsing failed: ${error.message}`);
}
if (!Array.isArray(data.compliance_mappings)) {
  throw new Error('Agent 5 output missing compliance_mappings[].');
}
data.compliance_mappings = data.compliance_mappings.map(m => {
  const validRequirement = allowedReqIds.has(m.requirement_id);
  if (!validRequirement) {
    m.requirement_type = 'best_practice';
    m.compliance_status = 'requires_verification';
  }
  m.evidence_ids = Array.isArray(m.evidence_ids)
    ? m.evidence_ids.filter(id => validEvIds.has(id))
    : [];
  if (m.evidence_ids.length === 0 && m.compliance_status === 'evidenced') {
    m.compliance_status = 'not_evidenced_requires_verification';
  }
  return m;
});
return [{
  json: {
    agent: 'A5',
    data,
    catalogue_version: catResp.catalogue_version || 'unknown',
    catalogue_requirement_count: catResp.requirements.length,
    validation_status: 'completed'
  }
}];

