const rawOut = $input.first().json.output || $input.first().json.text || '';
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const validEvIds = new Set(ext.chunks.map(c => c.evidence_id));
const cleaned = String(rawOut).replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Agent 6 did not return valid JSON.');
const data = JSON.parse(cleaned.slice(s, e + 1));
if (!Array.isArray(data.risk_findings)) throw new Error('Agent 6 output missing risk_findings[].');

data.risk_findings = data.risk_findings.map((r, i) => {
  r.risk_id = r.risk_id || `RSK-${String(i + 1).padStart(3, '0')}`;
  r.evidence_ids = (r.evidence_ids || []).filter(id => validEvIds.has(id));
  return r;
});
return [{ json: { agent: 'A6', data } }];

const ext = $('Validate Extraction & Build Evidence Store').last().json;
const a3 = $('Parse & Validate A3').last().json.data.activities || [];
const a4 = $('Parse & Validate A4').last().json.data || { entities: [], flows: [] };
const a6 = $('Parse & Validate A6').last().json.data.risk_findings || [];

const actIds = new Set(a3.map(a => a.activity_id));
const flowActIds = new Set((a4.flows || []).map(f => f.activity_id).filter(Boolean));
const activitiesWithoutFlows = [...actIds].filter(id => !flowActIds.has(id));
const activitiesWithoutEvidence = a3.filter(a => !a.evidence_ids || a.evidence_ids.length === 0).map(a => a.activity_id);
const orphanRisks = a6.filter(r => r.related_activity_id && !actIds.has(r.related_activity_id)).map(r => r.risk_id);

return JSON.stringify({
  total_evidence_chunks: ext.chunk_count,
  total_activities: a3.length,
  total_entities: (a4.entities || []).length,
  total_flows: (a4.flows || []).length,
  activities_without_flows: activitiesWithoutFlows,
  activities_without_evidence: activitiesWithoutEvidence,
  risks_with_unknown_activity_id: orphanRisks
});

const ext = $('Validate Extraction & Build Evidence Store').last().json;
const a3 = $('Parse & Validate A3').last().json.data.activities || [];
const a4 = $('Parse & Validate A4').last().json.data || { entities: [], flows: [] };
const a6 = $('Parse & Validate A6').last().json.data.risk_findings || [];

const actIds = new Set(a3.map(a => a.activity_id));
const flowActIds = new Set((a4.flows || []).map(f => f.activity_id).filter(Boolean));
const activitiesWithoutFlows = [...actIds].filter(id => !flowActIds.has(id));
const activitiesWithoutEvidence = a3.filter(a => !a.evidence_ids || a.evidence_ids.length === 0).map(a => a.activity_id);
const orphanRisks = a6.filter(r => r.related_activity_id && !actIds.has(r.related_activity_id)).map(r => r.risk_id);

return JSON.stringify({
  total_evidence_chunks: ext.chunk_count,
  total_activities: a3.length,
  total_entities: (a4.entities || []).length,
  total_flows: (a4.flows || []).length,
  activities_without_flows: activitiesWithoutFlows,
  activities_without_evidence: activitiesWithoutEvidence,
  risks_with_unknown_activity_id: orphanRisks
});

function readOutput(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!Array.isArray(items) || items.length === 0) return null;
    const value = items[items.length - 1]?.json;
    if (!value) return null;
    const candidate = value.output ?? value.text ?? value.response ?? value;
    if (typeof candidate === 'string') return candidate;
    if (candidate && typeof candidate === 'object') {
      if (typeof candidate.text === 'string') return candidate.text;
      if (typeof candidate.output === 'string') return candidate.output;
      return JSON.stringify(candidate);
    }
    return null;
  } catch (error) {
    return null;
  }
}

const primaryOutput = readOutput('Agent 7: QA & Evidence Review');
const fallbackOutput = readOutput('FallBack7');
const rawOut = primaryOutput || fallbackOutput;

if (!rawOut) {
  throw new Error('Agent 7 (Gemini) and FallBack7 (OpenRouter) returned no readable output.');
}

const extItems = $('Validate Extraction & Build Evidence Store').all();
const ext = extItems?.[extItems.length - 1]?.json;
if (!ext?.config) throw new Error('Extraction evidence/configuration is unavailable.');

const dbState = $input.first()?.json || {};
const qaAttemptsUsed = Math.max(0, Number(dbState.qa_attempts || 0));

const cleaned = String(rawOut)
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start < 0 || end < start) {
  throw new Error('Agent 7 did not return a JSON object. Check the model output and agent prompt.');
}

let qa;
try {
  qa = JSON.parse(cleaned.slice(start, end + 1));
} catch (error) {
  throw new Error(`Agent 7 JSON parsing failed: ${error.message}`);
}

if (!qa || typeof qa !== 'object' || Array.isArray(qa)) {
  throw new Error('Agent 7 response must be a JSON object.');
}

const allowedStatuses = ['ready_for_human_approval', 'approved', 'needs_revision'];
if (!allowedStatuses.includes(qa.review_status)) {
  throw new Error(
    `Invalid QA review_status "${qa.review_status}". Expected ready_for_human_approval or needs_revision.`
  );
}

if (qa.review_status === 'approved') qa.review_status = 'ready_for_human_approval';

const arrayFields = [
  'evidence_validation_findings',
  'contradiction_findings',
  'missing_information',
  'unsupported_claims',
  'correction_requests'
];
for (const field of arrayFields) {
  if (!Array.isArray(qa[field])) qa[field] = [];
}

const validTargets = new Set(['A3', 'A4', 'A5', 'A6']);
qa.correction_requests = qa.correction_requests
  .filter(r => r && typeof r === 'object' && validTargets.has(String(r.target_agent || '').toUpperCase()))
  .map(r => ({
    target_agent: String(r.target_agent).toUpperCase(),
    issue: String(r.issue || 'QA issue requires correction'),
    instruction: String(r.instruction || 'Review the cited evidence and correct the finding.')
  }));

const needsRevision = qa.review_status === 'needs_revision';
const maxRetries = Math.max(0, Number(ext.config.max_qa_revisions ?? 2));
const canRetry = needsRevision &&
  qa.correction_requests.length > 0 &&
  qaAttemptsUsed < maxRetries;
const manualInterventionRequired = needsRevision && !canRetry;

return [{
  json: {
    agent: 'A7',
    qa,
    qa_attempts_used: qaAttemptsUsed,
    trigger_qa_retry: canRetry,
    manual_intervention_required: manualInterventionRequired,
    model_provider: primaryOutput ? 'gemini' : 'openrouter_fallback'
  }
}];

const dbRow = $input.first().json;
const qaNode = $('Parse & Validate A7 (QA Gate)').last().json;
const reqs = Array.isArray(qaNode.qa.correction_requests) ? qaNode.qa.correction_requests : [];

const by_agent = { A3: [], A4: [], A5: [], A6: [] };
for (const r of reqs) {
  const t = String(r.target_agent || 'A3').toUpperCase().trim();
  if (by_agent[t]) by_agent[t].push(r);
  else by_agent.A3.push(r);
}

let earliest_target = 'A6';
if (by_agent.A3.length > 0) earliest_target = 'A3';
else if (by_agent.A4.length > 0) earliest_target = 'A4';
else if (by_agent.A5.length > 0) earliest_target = 'A5';

return [{
  json: {
    qa_attempt: Number(dbRow.qa_attempts || 1),
    earliest_target,
    by_agent,
    correction_requests: reqs
  }
}];

const a4 = $('Parse & Validate A4').last().json.data;
const ext = $('Validate Extraction & Build Evidence Store').last().json;
const safeId = s => 'N_' + String(s || '').replace(/[^A-Za-z0-9_]/g, '_');
const safeLbl = s => String(s == null ? '' : s).replace(/["\[\]\(\)\{\}<>|`#;]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 65);

const shapeFor = e => {
  const id = safeId(e.entity_id);
  const lbl = safeLbl(`${e.entity_id}: ${e.name}`);
  switch (e.entity_type) {
    case 'data_principal': return `${id}(["${lbl}"])`;
    case 'database':
    case 'storage_system': return `${id}[("${lbl}")]`;
    case 'data_processor':
    case 'third_party_vendor':
    case 'external_recipient': return `${id}{{"${lbl}"}}`;
    case 'internal_department': return `${id}[["${lbl}"]]`;
    default: return `${id}["${lbl}"]`;
  }
};

const l0Lines = ['flowchart LR'];
a4.entities.forEach(e => l0Lines.push('  ' + shapeFor(e)));
a4.flows.forEach(f => {
  const lbl = safeLbl((f.data_categories || []).slice(0, 3).join(', ') || f.processing_stage || 'data');
  const arrow = f.explicit_or_inferred === 'inferred' ? '-.->' : '-->';
  const tag = f.explicit_or_inferred === 'inferred' ? `${lbl} (inferred)` : lbl;
  l0Lines.push(`  ${safeId(f.source_entity_id)} ${arrow}|"${tag}"| ${safeId(f.destination_entity_id)}`);
});
l0Lines.push('  classDef ext fill:#ffe4e6,stroke:#e11d48,stroke-width:2px;');
l0Lines.push('  classDef db fill:#e0f2fe,stroke:#0284c7,stroke-width:2px;');

const l1Lines = ['flowchart TB'];
const groups = {};
for (const e of a4.entities) {
  const g = safeLbl(e.department_or_owner || e.entity_type || 'General').replace(/\s+/g, '_') || 'General';
  groups[g] = groups[g] || [];
  groups[g].push(e);
}
Object.keys(groups).forEach((g, idx) => {
  l1Lines.push(`  subgraph SG_${idx}["${g}"]`);
  groups[g].forEach(e => l1Lines.push('    ' + shapeFor(e)));
  l1Lines.push('  end');
});
a4.flows.forEach(f => {
  const lbl = safeLbl(`${f.flow_id} [${f.activity_id || 'ACT'}]: ${f.processing_stage}`);
  const arrow = f.explicit_or_inferred === 'inferred' ? '-.->' : '-->';
  l1Lines.push(`  ${safeId(f.source_entity_id)} ${arrow}|"${lbl}"| ${safeId(f.destination_entity_id)}`);
});

return [{
  json: {
    job_id: ext.job_id,
    tenant_id: ext.tenant_id,
    project_id: ext.project_id,
    level_0_mermaid: l0Lines.join('\n'),
    level_1_mermaid: l1Lines.join('\n'),
    diagram_generation_status: 'generated_source',
    rendered_svg_available: false,
    rendered_png_available: false
  }
}];

const ext = $('Validate Extraction & Build Evidence Store').last().json;
const a1 = ($('Parse & Validate A1').last().json.data.documents || [])[0] || {};
const a2 = $('Parse & Validate A2').last().json.data || {};
const a3 = $('Parse & Validate A3').last().json.data.activities || [];
const a4 = $('Parse & Validate A4').last().json.data || { entities: [], flows: [] };
const a5 = $('Parse & Validate A5').last().json.data.compliance_mappings || [];
const a6 = $('Parse & Validate A6').last().json.data.risk_findings || [];
const a7 = $('Parse & Validate A7 (QA Gate)').last().json;
const rawBriefing = $input.first()?.json?.output || $input.first()?.json?.text || 'Automated DPDP multi-agent analysis completed and ready for human review.';
const red = ext.document.redaction_summary || { pii_redaction_enabled: ext.document.pii_redacted, total_masked_tokens: 0, counts_by_type: {}, masked_locations: [] };

function formatBriefingHtml(text) {
  const lines = String(text || '').split(/\r?\n/);
  const htmlLines = [];
  for (let line of lines) {
    let trimmed = line.trim();
    if (!trimmed) continue;
    trimmed = trimmed
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
    const isBullet = /^[\*\-]\s+/.test(trimmed);
    if (isBullet) {
      trimmed = trimmed.replace(/^[\*\-]\s+/, '');
    }
    trimmed = trimmed.replace(/\*\*([^*]+?)\*\*/g, '<b>$1</b>');
    trimmed = trimmed.replace(/\*([^*]+?)\*/g, '<b>$1</b>');
    trimmed = trimmed.replace(/\*/g, '');
    if (isBullet) {
      htmlLines.push(`<div style="margin-left:18px;margin-bottom:4px;">• ${trimmed}</div>`);
    } else {
      htmlLines.push(`<p style="margin:6px 0;">${trimmed}</p>`);
    }
  }
  return htmlLines.join('\n');
}

const formattedBriefingHtml = formatBriefingHtml(rawBriefing);

const sqlCommands = `-- =====================================================================
-- JOB-SPECIFIC POSTGRESQL COMMANDS FOR JOB: ${ext.job_id}
-- Tenant: ${ext.tenant_id} | Project: ${ext.project_id} | Document: ${ext.document.filename}
-- Run directly in pgAdmin 4 Query Tool
-- =====================================================================

-- 1. Check Unmasked PII Vault (Original vs Redacted Text)
SELECT event_id, created_at, payload->'redaction_summary' AS summary, payload->'unmasked_vault' AS unmasked_original_text
FROM audit_events
WHERE job_id = '${ext.job_id}' AND event_type = 'PII_REDACTION_VAULT';

-- 2. Check Document Metadata, SHA-256 & Redaction Audit Trail
SELECT document_id, filename, sha256, page_count, pii_redacted, created_at
FROM documents
WHERE job_id = '${ext.job_id}' AND tenant_id = '${ext.tenant_id}' AND project_id = '${ext.project_id}';

-- 3. Check All Extracted Evidence Chunks & Masked Excerpts
SELECT evidence_id, locator, chunk_text
FROM document_chunks
WHERE job_id = '${ext.job_id}' AND tenant_id = '${ext.tenant_id}'
ORDER BY evidence_id ASC;

-- 4. Check Phrased Personal Data Items & Data Principals (After Approval Export)
SELECT item_id, category_name, description, sensitivity_or_impact, collection_source, processing_purpose, explicit_or_inferred, evidence_ids
FROM personal_data_items
WHERE job_id = '${ext.job_id}' AND tenant_id = '${ext.tenant_id}';

